import React from 'react';
import { useNavigate } from 'react-router-dom';

const HomePage = () => {
  const navigate = useNavigate();

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center">
      <div className="text-center">
        <h1 className="text-6xl font-bold text-blue-600 mb-4">MedConnect+</h1>
        <p className="text-2xl text-gray-700 mb-12">Hospital Management System</p>
        
        <div className="flex flex-col md:flex-row gap-6 justify-center items-center">
          {/* Doctor Button */}
          <button
            onClick={() => navigate('/login/doctor')}
            className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-6 px-12 rounded-lg text-xl shadow-lg transform transition hover:scale-105 flex items-center gap-4"
          >
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
            </svg>
            Doctor Login
          </button>

          {/* Patient Button */}
          <button
            onClick={() => navigate('/login/patient')}
            className="bg-green-600 hover:bg-green-700 text-white font-bold py-6 px-12 rounded-lg text-xl shadow-lg transform transition hover:scale-105 flex items-center gap-4"
          >
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" />
            </svg>
            Patient Login
          </button>
        </div>

        <div className="mt-12 text-gray-600">
          <p>Don't have an account? <a href="/register/doctor" className="text-blue-600 hover:underline">Register as Doctor</a> or <a href="/register" className="text-green-600 hover:underline">Register as Patient</a></p>
        </div>
      </div>
    </div>
  );
};

export default HomePage;
